raw_signs = VOL6_BASE + daily_extras
seen = set()
unique_signs = []
for s in raw_signs:
    if s[0] not in seen:
        seen.add(s[0])
        unique_signs.append(s)

final_200 = unique_signs[:200]
assert len(final_200) == 200, f"Expected 200 signs, got {len(final_200)}"

out_path = os.path.join("scripts", "volume_data", "vol6_daily.py")
with open(out_path, "w", encoding="utf-8") as f:
    f.write('"""\nVolume 6: Daily Necessities, Nutrition & Living Standards (200 Signs)\n"""\n\n')
    f.write("VOL6_DAILY_200 = [\n")
    for item in final_200:
        f.write(f"    {repr(item)},\n")
    f.write("]\n\n")
    f.write('assert len(VOL6_DAILY_200) == 200, f"Expected 200 signs, got {len(VOL6_DAILY_200)}"\n')

print(f"Successfully generated {out_path} with {len(final_200)} unique signs!")
